```javascript
const fs = require('fs');

function gcd(a, b) {
    while (b !== 0) {
        const t = b;
        b = a % b;
        a = t;
    }
    return a;
}

// Representação de um nó:
// len: tamanho do intervalo
// ans: número de subsequências candidatas
// pref: array de [g, c] onde g > 1
// suff: array de [g, c] onde g > 1
function merge(A, B) {
    if (!A) return B;
    if (!B) return A;

    let ans = A.ans + B.ans;

    // Cruzamento entre A.suff e B.pref
    const aSuff = A.suff;
    const bPref = B.pref;
    const sLen = aSuff.length;
    const pLen = bPref.length;

    for (let i = 0; i < sLen; i++) {
        const sg = aSuff[i][0];
        const sc = aSuff[i][1];
        for (let j = 0; j < pLen; j++) {
            if (gcd(sg, bPref[j][0]) > 1) {
                ans += sc * bPref[j][1];
            }
        }
    }

    // Construção de pref
    const pref = [];
    let prefLenSum = 0;
    for (let i = 0; i < A.pref.length; i++) {
        pref.push([A.pref[i][0], A.pref[i][1]]);
        prefLenSum += A.pref[i][1];
    }

    // Se todo o A tem GCD > 1, podemos estender prefixos para B
    if (prefLenSum === A.len && pref.length > 0) {
        let lastG = pref[pref.length - 1][0];
        for (let j = 0; j < bPref.length; j++) {
            const g = gcd(lastG, bPref[j][0]);
            if (g === 1) break; // Daqui em diante será 1
            const c = bPref[j][1];
            if (pref.length > 0 && pref[pref.length - 1][0] === g) {
                pref[pref.length - 1][1] += c;
            } else {
                pref.push([g, c]);
            }
        }
    }

    // Construção de suff
    const suff = [];
    let suffLenSum = 0;
    for (let i = 0; i < B.suff.length; i++) {
        suff.push([B.suff[i][0], B.suff[i][1]]);
        suffLenSum += B.suff[i][1];
    }

    // Se todo o B tem GCD > 1, podemos estender sufixos para A
    if (suffLenSum === B.len && suff.length > 0) {
        let lastG = suff[suff.length - 1][0];
        for (let i = 0; i < aSuff.length; i++) {
            const g = gcd(lastG, aSuff[i][0]);
            if (g === 1) break;
            const c = aSuff[i][1];
            if (suff.length > 0 && suff[suff.length - 1][0] === g) {
                suff[suff.length - 1][1] += c;
            } else {
                suff.push([g, c]);
            }
        }
    }

    return {
        len: A.len + B.len,
        ans: ans,
        pref: pref,
        suff: suff
    };
}

function makeLeaf(val) {
    if (val > 1) {
        return {
            len: 1,
            ans: 1,
            pref: [[val, 1]],
            suff: [[val, 1]]
        };
    } else {
        return {
            len: 1,
            ans: 0,
            pref: [],
            suff: []
        };
    }
}

function main() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function nextInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const N = nextInt();
    if (N === null) return;
    const M = nextInt();

    const S = new Int32Array(N + 1);
    for (let i = 1; i <= N; i++) {
        S[i] = nextInt();
    }

    const tree = new Array(4 * N);

    function build(node, l, r) {
        if (l === r) {
            tree[node] = makeLeaf(S[l]);
            return;
        }
        const mid = (l + r) >> 1;
        const leftChild = node << 1;
        const rightChild = leftChild | 1;
        build(leftChild, l, mid);
        build(rightChild, mid + 1, r);
        tree[node] = merge(tree[leftChild], tree[rightChild]);
    }

    function update(node, l, r, idx, val) {
        if (l === r) {
            tree[node] = makeLeaf(val);
            return;
        }
        const mid = (l + r) >> 1;
        const leftChild = node << 1;
        const rightChild = leftChild | 1;
        if (idx <= mid) {
            update(leftChild, l, mid, idx, val);
        } else {
            update(rightChild, mid + 1, r, idx, val);
        }
        tree[node] = merge(tree[leftChild], tree[rightChild]);
    }

    function query(node, l, r, ql, qr) {
        if (ql <= l && r <= qr) {
            return tree[node];
        }
        const mid = (l + r) >> 1;
        const leftChild = node << 1;
        const rightChild = leftChild | 1;

        if (qr <= mid) {
            return query(leftChild, l, mid, ql, qr);
        }
        if (ql > mid) {
            return query(rightChild, mid + 1, r, ql, qr);
        }
        const leftRes = query(leftChild, l, mid, ql, qr);
        const rightRes = query(rightChild, mid + 1, r, ql, qr);
        return merge(leftRes, rightRes);
    }

    build(1, 1, N);

    const out = [];
    for (let i = 0; i < M; i++) {
        const type = nextInt();
        if (type === 1) {
            const idx = nextInt();
            const val = nextInt();
            update(1, 1, N, idx, val);
        } else {
            const l = nextInt();
            const r = nextInt();
            const res = query(1, 1, N, l, r);
            out.push(res.ans);
            if (out.length >= 20000) {
                process.stdout.write(out.join('\n') + '\n');
                out.length = 0;
            }
        }
    }

    if (out.length > 0) {
        process.stdout.write(out.join('\n') + '\n');
    }
}

main();
